#!/usr/bin/env bash
# Generated by camcfg.py from arterial_32.yaml; edit the inventory and regenerate instead of editing this file.
# Stores the corridor's map in TeraSim (POST /v1/city/maps): copies the OpenStreetMap extract
# arterial_8.osm into the service's volume and lets the service convert it with its own
# OpenStreetMap import. Nothing is downloaded; the image is not rebuilt. Expected map id
# ed0947a56fee (the first 12 hex digits of the file's SHA-256), which scheduled_config.yaml names:
#   /data/output/store/maps/ed0947a56fee/base.sumocfg
# Usage: ./register-map.sh <path to arterial_8.osm>   (KUBECTL=kubectl for plain Kubernetes)
set -euo pipefail
FILE="${1:?usage: $0 <path to arterial_8.osm>}"
KUBECTL="${KUBECTL:-oc}"
TNS="${TNS:-terasim}"
SVC="${SVC:-deploy/terasim-phase1-service}"
"$KUBECTL" exec -n "$TNS" "$SVC" -- mkdir -p /data/output/uploads
"$KUBECTL" exec -i -n "$TNS" "$SVC" -- sh -c 'cat > /data/output/uploads/arterial_8.osm' < "$FILE"
"$KUBECTL" exec -n "$TNS" "$SVC" -- python -c 'import json,urllib.request as u
req=u.Request("http://127.0.0.1:8000/v1/city/maps",json.dumps({"path":"/data/output/uploads/arterial_8.osm"}).encode(),{"Content-Type":"application/json"})
print(u.urlopen(req,timeout=600).read().decode())'
echo "expected map_id: ed0947a56fee"
"$KUBECTL" exec -n "$TNS" "$SVC" -- test -f /data/output/store/maps/ed0947a56fee/base.sumocfg && echo "map ready: /data/output/store/maps/ed0947a56fee/base.sumocfg"
